create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',email text,grade int check(grade between 6 and 12),preferred_language text not null default 'English',avatar_url text,xp int not null default 0,current_streak int not null default 0,longest_streak int not null default 0,last_activity_date date,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists subjects(id uuid primary key default gen_random_uuid(),name text unique not null,slug text unique not null,icon text,color text,created_at timestamptz default now());
create table if not exists topics(id uuid primary key default gen_random_uuid(),subject_id uuid references subjects(id) on delete cascade,name text not null,slug text not null,description text,created_at timestamptz default now(),unique(subject_id,slug));
create table if not exists user_subjects(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id) on delete cascade,subject_id uuid references subjects(id) on delete cascade,created_at timestamptz default now(),unique(user_id,subject_id));
create table if not exists conversations(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id) on delete cascade,title text not null,subject_id uuid references subjects(id),created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists messages(id uuid primary key default gen_random_uuid(),conversation_id uuid references conversations(id) on delete cascade,user_id uuid references profiles(id) on delete cascade,role text check(role in ('user','assistant')) not null,content text not null,image_url text,created_at timestamptz default now());
create table if not exists quizzes(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id) on delete cascade,subject_id uuid references subjects(id),topic_id uuid references topics(id),difficulty text not null,number_of_questions int not null,score int,completed boolean not null default false,created_at timestamptz default now(),completed_at timestamptz);
create table if not exists quiz_questions(id uuid primary key default gen_random_uuid(),quiz_id uuid references quizzes(id) on delete cascade,question text not null,options jsonb not null,correct_answer text not null,explanation text,student_answer text,is_correct boolean,topic text,created_at timestamptz default now());
create table if not exists progress(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id) on delete cascade,subject_id uuid references subjects(id),topic_id uuid references topics(id),questions_attempted int not null default 0,questions_correct int not null default 0,accuracy numeric not null default 0,mastery_level numeric not null default 0,time_spent int not null default 0,updated_at timestamptz default now(),unique(user_id,subject_id,topic_id));
create table if not exists achievements(id uuid primary key default gen_random_uuid(),name text unique not null,description text,icon text,xp_reward int default 0,requirement_type text,requirement_value int);
create table if not exists user_achievements(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id) on delete cascade,achievement_id uuid references achievements(id) on delete cascade,earned_at timestamptz default now(),unique(user_id,achievement_id));
create table if not exists learning_activity(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id) on delete cascade,activity_type text not null,subject_id uuid references subjects(id),topic_id uuid references topics(id),xp_earned int not null default 0,created_at timestamptz default now());
create table if not exists recommendations(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id) on delete cascade,subject_id uuid references subjects(id),topic_id uuid references topics(id),title text not null,description text,reason text,completed boolean not null default false,created_at timestamptz default now());
create table if not exists uploaded_files(id uuid primary key default gen_random_uuid(),user_id uuid references profiles(id) on delete cascade,file_url text not null,file_type text,file_name text,created_at timestamptz default now());
create index if not exists idx_messages_conversation on messages(conversation_id,created_at);create index if not exists idx_activity_user on learning_activity(user_id,created_at);create index if not exists idx_progress_user on progress(user_id);
insert into subjects(name,slug,icon,color) values ('Mathematics','mathematics','🧮','blue'),('Physics','physics','⚡','orange'),('Chemistry','chemistry','🧪','purple') on conflict(name) do nothing;
insert into achievements(name,description,icon,xp_reward,requirement_type,requirement_value) values ('First Quiz','Complete your first quiz','🏆',25,'quizzes_completed',1),('7-Day Streak','Learn for seven consecutive days','🔥',75,'streak',7),('Problem Solver','Answer 10 quiz questions correctly','🧠',50,'correct_answers',10),('10 Lessons Completed','Complete ten learning sessions','📚',100,'sessions',10),('Mathematics Master','Reach 90% accuracy in Mathematics','⭐',150,'math_accuracy',90) on conflict(name) do nothing;
with s as (select id,name from subjects) insert into topics(subject_id,name,slug) select id,x,x from s cross join unnest(case when name='Mathematics' then array['Arithmetic','Algebra','Geometry','Trigonometry','Statistics','Equations','Graphs','Calculus'] when name='Physics' then array['Motion','Force','Energy','Electricity','Magnetism','Waves','Optics','Thermodynamics'] else array['Atoms','Molecules','Periodic Table','Chemical Equations','Chemical Bonding','Acids and Bases','Organic Chemistry','Stoichiometry'] end) x on conflict do nothing;

alter table profiles enable row level security;alter table user_subjects enable row level security;alter table conversations enable row level security;alter table messages enable row level security;alter table quizzes enable row level security;alter table quiz_questions enable row level security;alter table progress enable row level security;alter table user_achievements enable row level security;alter table learning_activity enable row level security;alter table recommendations enable row level security;alter table uploaded_files enable row level security;
alter table subjects enable row level security;alter table topics enable row level security;alter table achievements enable row level security;
create policy "public subjects" on subjects for select using(true);create policy "public topics" on topics for select using(true);create policy "public achievements" on achievements for select using(true);
create policy "own profiles" on profiles for all using(auth.uid()=id) with check(auth.uid()=id);create policy "own user subjects" on user_subjects for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own conversations" on conversations for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own messages" on messages for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own quizzes" on quizzes for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own quiz questions" on quiz_questions for all using(exists(select 1 from quizzes q where q.id=quiz_id and q.user_id=auth.uid())) with check(exists(select 1 from quizzes q where q.id=quiz_id and q.user_id=auth.uid()));create policy "own progress" on progress for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own achievements" on user_achievements for select using(auth.uid()=user_id);create policy "own activity" on learning_activity for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own recommendations" on recommendations for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own uploads" on uploaded_files for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name,email,grade,preferred_language) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),new.email,coalesce((new.raw_user_meta_data->>'grade')::int,10),coalesce(new.raw_user_meta_data->>'preferred_language','English')) on conflict(id) do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
create or replace function public.record_learning_activity(p_user_id uuid,p_activity_type text,p_xp int default 0) returns jsonb language plpgsql security definer set search_path=public as $$ declare p profiles%rowtype; today date:=current_date; begin if p_user_id<>auth.uid() then raise exception 'unauthorized'; end if; select * into p from profiles where id=p_user_id for update; if p.last_activity_date is null then p.current_streak:=1; elsif p.last_activity_date=today then null; elsif p.last_activity_date=today-1 then p.current_streak:=p.current_streak+1; else p.current_streak:=1; end if; p.longest_streak:=greatest(p.longest_streak,p.current_streak); p.xp:=p.xp+p_xp; p.last_activity_date:=today; update profiles set xp=p.xp,current_streak=p.current_streak,longest_streak=p.longest_streak,last_activity_date=today,updated_at=now() where id=p_user_id; insert into learning_activity(user_id,activity_type,xp_earned) values(p_user_id,p_activity_type,p_xp); return jsonb_build_object('xp',p.xp,'current_streak',p.current_streak); end; $$;
create or replace function public.record_quiz_progress(p_user_id uuid,p_subject_id uuid,p_topic_id uuid,p_questions_attempted int,p_questions_correct int,p_xp int) returns void language plpgsql security definer set search_path=public as $$ declare a numeric; begin if p_user_id<>auth.uid() then raise exception 'unauthorized';end if;a:=case when p_questions_attempted=0 then 0 else p_questions_correct::numeric/p_questions_attempted*100 end;insert into progress(user_id,subject_id,topic_id,questions_attempted,questions_correct,accuracy,mastery_level,updated_at) values(p_user_id,p_subject_id,p_topic_id,p_questions_attempted,p_questions_correct,a,a,now()) on conflict(user_id,subject_id,topic_id) do update set questions_attempted=progress.questions_attempted+excluded.questions_attempted,questions_correct=progress.questions_correct+excluded.questions_correct,accuracy=(progress.questions_correct+excluded.questions_correct)::numeric/(progress.questions_attempted+excluded.questions_attempted)*100,mastery_level=(progress.questions_correct+excluded.questions_correct)::numeric/(progress.questions_attempted+excluded.questions_attempted)*100,updated_at=now();perform record_learning_activity(p_user_id,'quiz',p_xp);end;$$;
create or replace function public.delete_my_account() returns void language plpgsql security definer set search_path=public as $$ begin delete from auth.users where id=auth.uid(); end;$$;

insert into storage.buckets(id,name,public) values ('student-files','student-files',false) on conflict(id) do nothing;
create policy "student files read own" on storage.objects for select to authenticated using (bucket_id='student-files' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "student files insert own" on storage.objects for insert to authenticated with check (bucket_id='student-files' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "student files delete own" on storage.objects for delete to authenticated using (bucket_id='student-files' and (storage.foldername(name))[1]=auth.uid()::text);
